<template>
	<div class="viewer" v-loading="loading">
		<header>
			<div><small>IOTSHARP TWIN 2D · PUBLISHED VIEWER</small><h2>{{ title }}</h2><p>v{{ versionNo || '-' }} · 只读生产运行态 · Telemetry Snapshot 1s</p></div>
			<div class="metrics"><el-tag type="success">Good {{ counts.good }}</el-tag><el-tag type="warning">Stale {{ counts.stale }}</el-tag><el-tag type="danger">Bad {{ counts.bad }}</el-tag><el-tag>Blocked {{ counts.blocked }}</el-tag></div>
			<div class="grow"/><el-button @click="router.push({path:'/iot/digital-twin/2d-scene',query:{sceneId}})">返回 2D 设计器</el-button><el-button @click="router.push({path:'/iot/digital-twin/scenes'})">场景中心</el-button><el-button @click="resetViewport">复位</el-button>
		</header>
		<main v-if="manifest" ref="stage">
			<svg ref="canvas" class="canvas" :viewBox="`${viewport.x} ${viewport.y} ${viewport.w} ${viewport.h}`" :style="{background:view.canvas.background}" @wheel.prevent="onWheel" @mousedown="onDown" @mousemove="onMove" @mouseup="onUp" @mouseleave="onUp" @click="runtimeVisible=false">
				<defs><pattern id="viewer-grid" :width="view.canvas.gridSize" :height="view.canvas.gridSize" patternUnits="userSpaceOnUse"><path :d="`M ${view.canvas.gridSize} 0 L 0 0 0 ${view.canvas.gridSize}`" fill="none" stroke="rgba(148,163,184,.12)" stroke-width="1" /></pattern></defs>
				<rect x="0" y="0" :width="view.canvas.width" :height="view.canvas.height" :fill="view.canvas.showGrid?'url(#viewer-grid)':view.canvas.background" />
				<template v-for="r in manifest.routes || []" :key="r.routeId"><line v-for="e in r.edges" :key="e.edgeId" v-bind="edgeLine(e)" class="route" :class="edgeClass(e)"/></template>
				<template v-for="r in manifest.routes || []" :key="`${r.routeId}:points`"><g v-for="p in r.points" :key="p.pointId"><circle :cx="routePoint(p.pointId).x" :cy="routePoint(p.pointId).y" r="5" class="point"/><text :x="routePoint(p.pointId).x+8" :y="routePoint(p.pointId).y-8" class="point-label">{{ p.name }}</text></g></template>
				<g v-for="p in routeSlotPallets" :key="p.key" class="route-slot-pallet" :transform="`translate(${p.x} ${p.y})`"><title>{{ p.routeName }} · 槽位 {{ p.slotIndex + 1 }} · 托盘 {{ p.palletId }}</title><rect x="-28" y="-18" width="56" height="36" rx="5"/><path d="M-21 -8 H21 M-21 0 H21 M-21 8 H21"/><text x="0" y="5" text-anchor="middle">{{ p.palletId }}</text></g>
				<g v-for="o in visibleObjects" :key="o.id" v-show="state(o).visible" class="object" :transform="transform(o)" :opacity="o.opacity ?? 1" @click.stop="showRuntime(o)"><Twin2DSymbol :item="o" :runtime="state(o)"/></g>
			</svg>
			<div v-if="view.showMinimap" class="minimap"><svg :viewBox="`0 0 ${view.canvas.width} ${view.canvas.height}`" preserveAspectRatio="none"><rect width="100%" height="100%" fill="#07111f"/><rect v-for="o in visibleObjects" :key="o.id" :x="o.x" :y="o.y" :width="o.width" :height="o.height" fill="#38bdf8" opacity=".6"/><rect :x="viewport.x" :y="viewport.y" :width="viewport.w" :height="viewport.h" fill="none" stroke="#facc15" stroke-width="12"/></svg></div>
			<div v-if="runtimeVisible && runtimeObject && runtimeAnchor.visible" class="runtime-popover" :class="`is-${runtimeCardPlacement.side}`" :style="runtimeCardPlacement.cardStyle" @click.stop @mousedown.stop>
				<div class="runtime-popover__arrow" :style="runtimeCardPlacement.arrowStyle"/><div class="runtime-popover__head"><div><small>OBJECT STATUS</small><strong>{{ runtimeObject.name }}</strong><span>{{ runtimeObject.businessObjectId || runtimeObject.id }}</span></div><div><em :class="statusTone(runtimeObject)">{{ state(runtimeObject).statusText }}</em><button type="button" @click="runtimeVisible=false">×</button></div></div>
				<div class="runtime-popover__grid"><div><label>信号</label><b>{{ signalSummary(runtimeObject) }}</b></div><div><label>位置</label><b>{{ runtimePosition(runtimeObject) }}</b></div><div><label>Quality</label><b>{{ state(runtimeObject).quality }}</b></div><div><label>路线</label><b>{{ state(runtimeObject).routeProgress===undefined?'-':`${(state(runtimeObject).routeProgress!*100).toFixed(1)}%` }}</b></div><div><label>占用</label><b>{{ state(runtimeObject).occupancy ?? '-' }} / {{ state(runtimeObject).capacity ?? '-' }}</b></div><div><label>预留</label><b>{{ state(runtimeObject).reserved ?? '-' }}</b></div></div>
				<div v-if="Object.keys(state(runtimeObject).values).length" class="runtime-popover__signals"><div v-for="([key,value]) in Object.entries(state(runtimeObject).values).slice(0,4)" :key="key"><span>{{ key }}</span><code>{{ value }}</code></div></div><div v-else class="runtime-popover__empty">暂无实时点位值</div>
			</div>
		</main>
		<el-result v-else-if="!loading" icon="warning" title="无法加载 2D 发布版本" :sub-title="errorText"/>
		<footer><span>Objects {{ view.objects.length }}</span><span>PLC Pallets {{ routeSlotPallets.length }}</span><span>Bindings {{ manifest?.bindings?.length || 0 }}</span><span>Routes {{ manifest?.routes?.length || 0 }}</span><span>{{ polling?'Telemetry polling':'Telemetry paused' }}</span><span>Zoom {{ zoomPercent }}%</span></footer>
	</div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { useRoute, useRouter } from 'vue-router';
import { digitalTwinApi, type DigitalTwinSceneDetail, type TwinDataUpdate, type TwinRuntimeSnapshot } from '/@/api/digital-twin';
import type { TwinSceneManifest } from '/@/digital-twin/contracts';
import { parseRouteSlotArray, routeSlotProgress } from '/@/digital-twin/bindings/RouteSlotArray';
import { ensureTwin2DView, type Twin2DObjectView, type Twin2DViewDefinition, type TwinSceneManifestWith2D } from '/@/digital-twin-2d/types';
import { interpolateTwin2DRoute, resolveTwin2DRouteRuntimeStates, resolveTwin2DRuntimeStates, type Twin2DObjectRuntimeState } from '/@/digital-twin-2d/runtime';
import Twin2DSymbol from '/@/digital-twin-2d/components/Twin2DSymbol.vue';
import { buildRuntimeStatusCardPlacement } from '/@/digital-twin/runtime/RuntimeStatusUiSupport';
const route=useRoute(),router=useRouter(),apiData=<T,>(r:any):T=>r.data as T;
const loading=ref(true),polling=ref(false),errorText=ref(''),title=ref('2D 发布运行态'),versionNo=ref(0),runtimeUpdates=ref<TwinDataUpdate[]>([]),manifest=ref<TwinSceneManifest>(),view=ref<Twin2DViewDefinition>({version:1,canvas:{width:4800,height:3000,background:'#07111f',gridSize:20,showGrid:true,snapToGrid:true},objects:[],routePoints:{},layers:[],showMinimap:true});
const sceneId=String(route.query.sceneId||''),requestedVersion=Number(route.query.version||0);const viewport=reactive({x:0,y:0,w:2400,h:1500}),zoomPercent=computed(()=>Math.round(4800/viewport.w*100));const canvas=ref<SVGSVGElement>(),stage=ref<HTMLElement>(),runtimeVisible=ref(false),runtimeObject=ref<Twin2DObjectView>();const runtimeAnchor=reactive({x:0,y:0,width:1,height:1,visible:false});let pan:{x:number,y:number,vx:number,vy:number}|undefined,pollTimer:number|undefined,lastSig='',anchorFrame=0;
const layerMap=computed(()=>new Map((view.value.layers||[]).map(l=>[l.id,l])));const visibleObjects=computed(()=>[...view.value.objects].filter(o=>!o.hidden&&layerMap.value.get(o.layerId||'production')?.visible!==false).sort((a,b)=>a.zIndex-b.zIndex));const states=computed(()=>manifest.value?resolveTwin2DRuntimeStates(view.value.objects,manifest.value,runtimeUpdates.value):{});const routeStates=computed(()=>manifest.value?resolveTwin2DRouteRuntimeStates(manifest.value,runtimeUpdates.value):{});const counts=computed(()=>Object.values(states.value).reduce((a,s)=>{if(s.quality==='stale')a.stale++;else if(['bad','missing'].includes(s.quality))a.bad++;else a.good++;if(s.blocked)a.blocked++;return a},{good:0,stale:0,bad:0,blocked:0}));
const routeSlotPallets=computed(()=>{if(!manifest.value)return[];const updates=new Map<string,TwinDataUpdate>();for(const update of runtimeUpdates.value){updates.set(update.bindingKey,update);updates.set(update.bindingId,update)}const result:Array<{key:string;palletId:string;slotIndex:number;x:number;y:number;routeName:string}>=[];for(const binding of manifest.value.bindings||[]){if(binding.enabled===false||binding.transform.kind!=='routeSlotArray')continue;const update=updates.get(binding.bindingId);if(!update||update.stale||['bad','missing','stale'].includes(update.quality))continue;const routeId=String((binding.transform as Record<string,unknown>).routeId||'').trim()||String(binding.target.property||'').replace(/^routeSlots:/,'');const routeDef=manifest.value.routes.find(item=>item.routeId===routeId);if(!routeDef)continue;const emptyValue=(binding.transform as Record<string,unknown>).emptyValue??0;for(const slot of parseRouteSlotArray(update.value,emptyValue)){const progress=routeSlotProgress(slot.slotIndex,slot.slotCount,routeDef.loop===true);const position=interpolateTwin2DRoute(manifest.value,view.value.routePoints,progress,routeId);if(position)result.push({key:`${binding.bindingId}:${slot.palletId}`,palletId:slot.palletId,slotIndex:slot.slotIndex,x:position.x,y:position.y,routeName:routeDef.name})}}return result});
const state=(o:Twin2DObjectView):Twin2DObjectRuntimeState=>states.value[o.id]||{quality:'good',running:false,fault:false,visible:true,blocked:false,waiting:false,statusText:'UNBOUND',values:{}};const routePoint=(id:string)=>view.value.routePoints[id]||{x:0,y:0};const edgeLine=(e:any)=>{const a=routePoint(e.fromPointId),b=routePoint(e.toPointId);return{x1:a.x,y1:a.y,x2:b.x,y2:b.y}};const edgeClass=(e:any)=>({blocked:routeStates.value[e.edgeId]?.blocked,stale:routeStates.value[e.edgeId]?.stale});const transform=(o:Twin2DObjectView)=>{const s=state(o),moving=['pallet','carton','agv'].includes(o.symbolKey)&&s.routeProgress!==undefined&&manifest.value?interpolateTwin2DRoute(manifest.value,view.value.routePoints,s.routeProgress):undefined;const x=moving?moving.x-o.width/2:o.x,y=moving?moving.y-o.height/2:o.y;return `translate(${x} ${y}) rotate(${o.rotation} ${o.width/2} ${o.height/2})`};
const runtimePosition=(o:Twin2DObjectView)=>{const s=state(o),moving=['pallet','carton','agv'].includes(o.symbolKey)&&s.routeProgress!==undefined&&manifest.value?interpolateTwin2DRoute(manifest.value,view.value.routePoints,s.routeProgress):undefined;const x=moving?.x??(o.x+o.width/2),y=moving?.y??(o.y+o.height/2);return `X ${x.toFixed(1)} · Y ${y.toFixed(1)}`};const signalSummary=(o:Twin2DObjectView)=>{const count=o.businessObjectId?(manifest.value?.bindings||[]).filter(b=>b.objectId===o.businessObjectId&&b.enabled!==false).length:0,received=Object.keys(state(o).values).length;return count?`${received}/${count} 条已收到`:'未绑定信号'};
const runtimeAnchorPoint=(o:Twin2DObjectView)=>{const s=state(o),moving=['pallet','carton','agv'].includes(o.symbolKey)&&s.routeProgress!==undefined&&manifest.value?interpolateTwin2DRoute(manifest.value,view.value.routePoints,s.routeProgress):undefined;return{x:moving?.x??(o.x+o.width/2),y:moving?moving.y-o.height/2:o.y}};
const runtimeCardPlacement=computed(()=>buildRuntimeStatusCardPlacement(runtimeAnchor,332,16,14));
const statusTone=(o:Twin2DObjectView)=>{const s=state(o);return s.fault||['bad','missing'].includes(s.quality)?'is-danger':s.quality==='stale'||s.waiting?'is-warn':s.running||s.quality==='good'?'is-good':'is-info'};
const updateRuntimeAnchor=()=>{if(runtimeVisible.value&&runtimeObject.value&&canvas.value&&stage.value){const p=runtimeAnchorPoint(runtimeObject.value),svgPoint=canvas.value.createSVGPoint();svgPoint.x=p.x;svgPoint.y=p.y;const matrix=canvas.value.getScreenCTM();if(matrix){const client=svgPoint.matrixTransform(matrix),rect=stage.value.getBoundingClientRect();Object.assign(runtimeAnchor,{x:client.x-rect.left,y:client.y-rect.top,width:rect.width,height:rect.height,visible:client.x>=rect.left&&client.x<=rect.right&&client.y>=rect.top&&client.y<=rect.bottom})}else runtimeAnchor.visible=false}else runtimeAnchor.visible=false;anchorFrame=requestAnimationFrame(updateRuntimeAnchor)};
const resetViewport=()=>Object.assign(viewport,{x:0,y:0,w:2400,h:1500});const zoom=(f:number)=>{const cx=viewport.x+viewport.w/2,cy=viewport.y+viewport.h/2;viewport.w=Math.max(300,Math.min(view.value.canvas.width*1.2,viewport.w*f));viewport.h=viewport.w*(1500/2400);viewport.x=cx-viewport.w/2;viewport.y=cy-viewport.h/2};const onWheel=(e:WheelEvent)=>zoom(e.deltaY<0?.9:1.1);const onDown=(e:MouseEvent)=>{if(e.button!==0&&e.button!==1)return;pan={x:e.clientX,y:e.clientY,vx:viewport.x,vy:viewport.y}};const onMove=(e:MouseEvent)=>{if(!pan)return;const scale=viewport.w/(canvas.value?.clientWidth||1);viewport.x=pan.vx-(e.clientX-pan.x)*scale;viewport.y=pan.vy-(e.clientY-pan.y)*scale};const onUp=()=>pan=undefined;
const poll=async()=>{if(!sceneId||!versionNo.value)return;try{const s=apiData<TwinRuntimeSnapshot>(await digitalTwinApi.snapshot(sceneId,versionNo.value));const next=s?.updates||[];const sig=JSON.stringify(next.map((x:any)=>[x.bindingId,x.value,x.quality,x.stale]));if(sig!==lastSig){runtimeUpdates.value=next;lastSig=sig}}catch(e:any){ElMessage.warning(e?.msg||e?.message||'Telemetry Snapshot 获取失败');stopPolling()}};const startPolling=()=>{stopPolling();polling.value=true;poll();pollTimer=window.setInterval(poll,1000)};const stopPolling=()=>{polling.value=false;if(pollTimer)window.clearInterval(pollTimer);pollTimer=undefined};
const load=async()=>{loading.value=true;try{if(!sceneId)throw new Error('缺少 sceneId');const scene=apiData<DigitalTwinSceneDetail>(await digitalTwinApi.getScene(sceneId));title.value=scene.name;const v=requestedVersion||scene.publishedVersion||0;if(!v)throw new Error('该场景尚未发布');versionNo.value=v;const version:any=apiData(await digitalTwinApi.getVersion(sceneId,v));const m=(version.manifest||version.manifestSnapshot||version.payload) as TwinSceneManifest;if(!m)throw new Error(`发布版本 v${v} 缺少 Manifest 快照`);manifest.value=structuredClone(m);view.value=ensureTwin2DView(manifest.value as TwinSceneManifestWith2D);startPolling()}catch(e:any){errorText.value=e?.msg||e?.message||'加载失败';manifest.value=undefined}finally{loading.value=false}};const showRuntime=(o:Twin2DObjectView)=>{runtimeObject.value=o;runtimeVisible.value=true};onMounted(()=>{anchorFrame=requestAnimationFrame(updateRuntimeAnchor);void load()});onBeforeUnmount(()=>{if(anchorFrame)cancelAnimationFrame(anchorFrame);stopPolling()});
</script>
<style scoped lang="scss">
