rgba(56,189,248,.42);transform:translateX(-50%) rotate(45deg)}.runtime-popover__head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;padding-bottom:8px;border-bottom:1px solid rgba(148,163,184,.15)}.runtime-popover__head>div{display:flex;min-width:0;align-items:center;gap:6px}.runtime-popover__head>div:first-child{align-items:flex-start;flex-direction:column;gap:2px}.runtime-popover__head small{font-size:8px;letter-spacing:.13em;color:#38bdf8}.runtime-popover__head strong{max-width:190px;overflow:hidden;color:#f8fafc;text-overflow:ellipsis;white-space:nowrap}.runtime-popover__head span{max-width:190px;overflow:hidden;font-size:9px;color:#64748b;text-overflow:ellipsis;white-space:nowrap}.runtime-popover__head em{padding:3px 6px;border-radius:10px;font-size:8px;font-style:normal}.runtime-popover__head em.is-good{background:rgba(34,197,94,.18);color:#86efac}.runtime-popover__head em.is-warn{background:rgba(245,158,11,.18);color:#fcd34d}.runtime-popover__head em.is-danger{background:rgba(239,68,68,.18);color:#fca5a5}.runtime-popover__head em.is-info{background:rgba(148,163,184,.15);color:#cbd5e1}.runtime-popover__head button{width:21px;height:21px;padding:0;border:0;border-radius:6px;background:rgba(148,163,184,.12);color:#94a3b8;font-size:16px;cursor:pointer}.runtime-popover__grid{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px}.runtime-popover__grid>div{display:flex;min-width:0;flex-direction:column;gap:2px;padding:5px 6px;border-radius:6px;background:rgba(15,31,52,.68)}.runtime-popover__grid label{font-size:8px;color:#64748b}.runtime-popover__grid b{overflow:hidden;font-size:9px;font-weight:500;color:#cbd5e1;text-overflow:ellipsis;white-space:nowrap}.runtime-popover__signals{display:grid;gap:3px;margin-top:7px}.runtime-popover__signals>div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px;padding:4px 6px;border-radius:5px;background:rgba(15,31,52,.5);font-size:9px}.runtime-popover__signals span{overflow:hidden;color:#94a3b8;text-overflow:ellipsis;white-space:nowrap}.runtime-popover__signals code{color:#f8fafc}.runtime-popover__empty{margin-top:7px;font-size:9px;color:#64748b}
</style>
